// initialize fixed blocks on scroll
function initStickyScrollBlock() {
    ResponsiveHelper.addRange({
        '..768': {
            on: function() {
                jQuery('.search-navigation').stickyScrollBlock({
                    setBoxHeight: true,
                    activeClass: 'fixed-position',
                    positionType: 'fixed',
                    extraTop: function() {
                        var totalHeight = 0;
                        jQuery('#header').each(function() {
                            totalHeight += jQuery(this).outerHeight();
                        });
                        return totalHeight;
                    }
                });
            },
            off: function() {
                jQuery('.search-navigation').stickyScrollBlock('destroy');
            }
        }
    });
}

;(function(){
	// detect device type
	var isTouchDevice = /Windows Phone/.test(navigator.userAgent) || ('ontouchstart' in window) || window.DocumentTouch && document instanceof DocumentTouch;
	var page = document.querySelector('html');
	if (isTouchDevice) {
		page.classList.add('touch-device');
	} else {
		page.classList.add('desktop-device');
	}
}());

// initialize smooth anchor links
function initAnchors() {
	var win = jQuery(window);
	var scrollInst = new SmoothScroll({
		// anchorLinks: 'a[href^="#"]:not([href="#"]).counter',
		anchorLinks: 'a[href^="#"]:not([href="#"]).counter, a[href^="#"]:not([href="#"]).helptopic',
		activeClasses: 'parent',
		extraOffset: 10,
		wheelBehavior: 'none',
		extraOffset: function() {
			var totalHeight = 10;

			ResponsiveHelper.addRange({
				'..767': {
					on: function() {
						jQuery('#header').each(function() {
							var $box = jQuery(this);
							totalHeight += $box.css('position') === 'fixed' ? $box.outerHeight() : 10;
						});
					}
				},
				'768..': {
					on: function() {
						totalHeight = 10;
					}
				}
			});
			return totalHeight;
		}
	});

	new SmoothScroll({
		anchorLinks: 'a[href^="#"]:not([href="#"]).btn-top',
		activeClasses: 'parent',
		wheelBehavior: 'none'
	});

	function reinitSmoothScroll(container) {
		win.off('resize.ss load.ss orientationchange.ss refreshAnchor.ss', scrollInst.resizeHandler);
		scrollInst.scrollContainer.off('scroll.ss', scrollInst.scrollHandler);
		scrollInst.options.container = container;
		scrollInst.options.container = container;
		scrollInst.container = scrollInst.options.container ? jQuery(scrollInst.options.container) : jQuery('html,body');
		scrollInst.scrollContainer = scrollInst.options.container ? scrollInst.container : win;

		scrollInst.scrollContainer.on('scroll.ss', scrollInst.scrollHandler);
		win.on('resize.ss load.ss orientationchange.ss refreshAnchor.ss', scrollInst.resizeHandler);
	}

	ResponsiveHelper.addRange({
		'..767': {
			on: function() {
				if (scrollInst) {
					reinitSmoothScroll(null);
					jQuery(window).trigger('resize.ss');
				}
			}
		},
		'768..': {
			on: function() {
				if (scrollInst) {
					reinitSmoothScroll('.holder-section > .help-col');
					jQuery(window).trigger('resize.ss');
				}
			}
		}
	});

	jQuery(window).trigger('resize');
}

// initialize custom form elements
function initCustomForms() {
	jcf.setOptions('Select', {
		wrapNative: false,
		wrapNativeOnMobile: false,
	});
	jcf.replaceAll();

	jQuery('[type="range"]').on('input change setDataValue', function() {
		var jcfInst = jQuery(this).data('jcfInstance');

		if (jcfInst) {
			jcfInst.handles[0].setAttribute('data-value', jcfInst.values[0] < 10 ? ('0' + jcfInst.values[0]) : jcfInst.values[0]);
		}
	}).trigger('setDataValue');

	jQuery('form').on('reset', function() {
		var form = jQuery(this);

		setTimeout(function() {
			form.find('[type="range"]').each(function() {
				var jcfInst = jQuery(this).data('jcfInstance');

				if (jcfInst) {
					jcfInst.values = jcfInst.isMultiple ? jcfInst.realElement.attr('value').split(',') : [jcfInst.realElement.val()];

					jcfInst.refresh();

					jQuery(this).trigger('setDataValue');
				}
			});
		}, 0);
	});

}

jQuery(document).ajaxComplete(function() {
	jcf.replaceAll('#js-page-holder');
});

// init ClipboardJS
function initClipboardJS() {
	var clipboard = new ClipboardJS('[data-clipboard-text]');

	jQuery(document).on('click', '[data-clipboard-text]', function(e) {
		e.preventDefault();
	});

	clipboard.on('success', function(e) {
		var button = e.trigger;
		button.classList.remove('error');
		button.classList.add('success');

		button.timer && clearTimeout(button.timer);

		button.timer = setTimeout(function() {
			button.classList.remove('success');
		}, 1000)

		e.clearSelection();
	});

	clipboard.on('error', function(e) {
		var button = e.trigger;
		button.classList.remove('success');
		button.classList.add('error');

		button.timer && clearTimeout(button.timer);

		button.timer = setTimeout(function() {
			button.classList.remove('error');
		}, 1000)
	});
}

// mobile menu init
function initMobileNav() {
	var searchInst = jQuery('#header').mobileNav({
		menuActiveClass: 'search-active',
		menuOpener: '.nav-opener.search'
	}).data('MobileNav');

	var menuInst = jQuery('#header').mobileNav({
		menuActiveClass: 'burger-active',
		menuOpener: '.nav-opener.burger'
	}).data('MobileNav');

	jQuery('#sidebar').mobileNav({
		menuActiveClass: 'browse-active',
		menuOpener: '.browse-opener'
	});

	jQuery('#header form').on('submit', function() {
		if (searchInst && searchInst.isOpened()) {
			searchInst.hide();
			jQuery(this).find('input').blur();
		}
	});

	jQuery('#header a[data-page-type]').on('click', function() {
		if (menuInst && menuInst.isOpened()) {
			menuInst.hide();
		}
	});
}

function hideBrowse() {
	var browseNavInst = jQuery('#sidebar').data('MobileNav');

	if (browseNavInst && browseNavInst.isOpened()) {
		browseNavInst.hide();
	}
}

// accordion menu init
function initAccordion(context) {
	var content = context || jQuery('body');

	content.find('.tab-accordion').slideAccordion({
		opener: '>.opener',
		slider: '>.slide',
		animSpeed: 300,
		scrollToActiveItem: {
			enable: false,
			extraOffset: 0
		}
	});
}

function initIFrameResize(iframe) {
	if (iframe.is('#js-pdf-viewer')) return;
	// detect device type
	var isTouchDevice = /Windows Phone/.test(navigator.userAgent) || ('ontouchstart' in window) || window.DocumentTouch && document instanceof DocumentTouch;
	var refreshTimer = null;
	var deferred = jQuery.Deferred();

	iframe.attr('scrolling', isTouchDevice ? 'no' : 'auto');

	function refreshIframeHeight() {
		clearTimeout(refreshTimer);

		refreshTimer = setTimeout(function() {
            iframe.css('height', '300px');

            iframe.css('height', Math.ceil(Math.max(iframe.contents().find('body').outerHeight(true), iframe.contents().find('body').prop('scrollHeight'))));
            iframe.css('height', 50 + Math.ceil(Math.max(iframe.contents().find('body').outerHeight(true), iframe.contents().find('body').prop('scrollHeight'))));

            deferred.resolve(iframe);
		}, 200);
	}

	refreshIframeHeight();

	jQuery(window).on('resize orientationchange refreshIframeHeight', refreshIframeHeight);

	return deferred;
}

// ajax request function
function ajaxRequest(url, data) {
	jQuery('#js-page-holder').addClass('page-content-loading');

	// abort previous request if not completed
	if (window.acXHR && typeof window.acXHR.abort === 'function') window.acXHR.abort();

	// start new request
	window.acXHR = jQuery.ajax({
		url: url || '/',
		dataType: 'text',
		data: data || '',
		success: function(response) {
			// updating results
			updatePageContent(response);
		},
		error: function(error) {
			// ajax error handling
			ajaxError(error);
		},
		complete: function() {
			// ajax complete handling
			ajaxComplete();
		}
	});
}

// on ajax complete
function ajaxComplete() {
	jQuery('#js-page-holder').removeClass('page-content-loading');
}

// on ajax error
function ajaxError(error) {
	console.log(error);
}

// update page content
function updatePageContent(response) {
	var pageTarget = jQuery('#js-page-holder');

	pageTarget.html(response);
	pageTarget.removeClass('hide-search-bar');

	// reinit plugins
	initTabs(pageTarget);
	initAccordion(pageTarget);
	initOpenClose(pageTarget);
    initStickyScrollBlock();
	initAnchors();
	initIframeEvents();
	// hide browse
	hideBrowse();
}

// update document
function updateDocument(src, viewerId, needReloadIframe, needStayNav) {
	var viewerHolderId = 'js-viewer-holder';
	var pageTarget = jQuery('#js-page-holder');
	var iframe = jQuery('#' + viewerId);
	var iframeTpl = '<iframe id="' + viewerId + '" src="' + src + '" frameborder="0">';
	var viewerTarget = jQuery('#' + viewerHolderId);

	if (!viewerTarget.length) {
		pageTarget.empty().append(
			viewerTarget = jQuery('<div id="' + viewerHolderId + '">')
		);
	}

	if (iframe.length && !needReloadIframe) {
		iframe.attr('src', src);
	} else {
		iframe = jQuery(iframeTpl);
		viewerTarget.html(iframe);
	}

	// remove search navigation

	if (!needStayNav) {
		jQuery('.search-navigation').remove();
	}

	// reinit iframe click function
	initIframeEvents();
}

// update search document
function updateSearchDocument(response) {
	var pageTarget = jQuery('#js-search-doc');

	pageTarget.html(response);

	initIframeEvents();
    initStickyScrollBlock();
}

// update (next/prev) search results
function updateSearchResults(link) {
	var acXHRData = link.data('acXHR');
	var pageTarget = jQuery('#js-search-doc');

	// abort previous request if not completed
	if (acXHRData && typeof acXHRData.abort === 'function') acXHRData.abort();

	pageTarget.addClass('search-doc-loading');

	// start new request
	var acXHR = jQuery.ajax({
		url: link.attr('href') || '/',
		dataType: 'text',
		success: function(response) {
			// updating results
			updateSearchDocument(response);
		},
		error: function(error) {
			// ajax error handling
			console.log(error);
		},
		complete: function() {
			// ajax complete handling
			pageTarget.removeClass('search-doc-loading');
		}
	});

	link.data('acXHR', acXHR);
}


// update Copy Src
function updateCopySrc(text) {
	jQuery('[data-clipboard-text]').attr('data-clipboard-text', text);
}


// init ajax page load
function initAjaxPage() {
	jQuery(document).on('click', '[data-page-type="ajax"]', loadContent);

	function loadContent(e) {
		if (e) {
			e.preventDefault();
		}

		ajaxRequest(jQuery(this).attr('href'));
	}
}

// init ajax search
function initAjaxSearch() {
	jQuery(document).on('submit', '[data-form-type="ajax"]', loadContent);

	function loadContent(e) {
		if (e) {
			e.preventDefault();
		}

		ajaxRequest(this.getAttribute('action'), jQuery(this).serialize());
	}
}

// init ajax navigation doc
function initAjaxNavDoc() {
	jQuery(document).on('click', '.js-search-doc-view', loadContent);

	function loadContent(e) {
		if (e) {
			e.preventDefault();
		}

		updateSearchResults(jQuery(this));

		if (jQuery(this).hasClass('search-word-line')) {
			jQuery('#js-page-holder').addClass('hide-search-bar');
		}
	}
}

