// init open pdf file
function initOpenPdf() {
	jQuery(document).on('click', '.js-pdf-view', function(e) {
		e.preventDefault();

		if (this.getAttribute('href') !== '' && this.getAttribute('href') !== '#') {
			updateDocument(this.href, 'js-pdf-viewer', true, this.getAttribute('data-from-search'));
		}
	});
}

// init load table of contents
function initLoadTOC() {
	jQuery(document).on('click', '[data-toc-url], [data-toc-form-url]', function(e) {
		var link = jQuery(this);
		var isForm = link.attr('data-toc-form-url');

		var href = link.attr('href');
		if (href && href !== '#') {
			//console.log('allow to open...', href);
			// not preventing default to allow doc to open
            openTocFile(href, link.attr('title'), true, $(this).data('nodeId'), link.data('path'));
            e.preventDefault();
		}
		else {
            e.preventDefault();
        }

		var acXHRData = link.data('acXHR');

		if (link.attr('nodes-loaded')) return;

		// abort previous request if not completed
		if (acXHRData && typeof acXHRData.abort === 'function') acXHRData.abort();

		link.addClass('toc-loading');

		// start new request
		var acXHR = jQuery.ajax({
			url: link.attr('data-toc-url') || link.attr('data-toc-form-url') || '/',
			dataType: 'text',
			success: function(response) {
				// updating results
				var tocNodes = jQuery(response);

				if (isForm)
					tocNodes.insertAfter(link.parent());
				else
					tocNodes.insertAfter(link);

				link.attr('nodes-loaded', true).trigger('nodes-loaded');

				ResponsiveHelper.addRange({
					'768..': {
						on: function() {
							link.closest('li').addClass('active');
						}
					}
				});

                //setTimeout(function () {
					if (isForm) {
                    	initOpenClose(jQuery('#sidebar'));
                    	jQuery('.open-fieldset .toc-accordion').trigger('change', link.parent().find('[type="checkbox"]'));
					}
					else
                    	initOpenClose(jQuery('#sidebar'));
                //}, 50);
				// initOpenClose(jQuery('#sidebar'));
			},
			error: function(error) {
				// ajax error handling
				console.log(error);
			},
			complete: function() {
				// ajax complete handling
				link.removeClass('toc-loading');
			}
		});

		link.data('acXHR', acXHR);
	});

}

// init mobile TOC
function initMobileTOC() {
	var activeLinkClass = 'mob-active';
	var activeItemClass = 'item-active';
	var inactiveItemClass = 'item-inactive';

	jQuery('.toc-holder').each(function() {
		var holder = jQuery(this);
		var bradcrumbs = holder.find('.toc-breadcrumbs');
		var nav = holder.find('.toc-accordion > li > ul').css('position', 'relative');
		var items = nav.find('li');
		var bradcrumbsItems = [];
		var defaultBradcrumbText = bradcrumbs.data('defaultBradcrumbText') || bradcrumbs.find('li').eq(0).text();

		// add classes if item has dropdown
		nav.find('li').each(function() {
			var item = jQuery(this);
			var drop = item.find('> ul');
			var link = item.find('> a');

			if(drop.length) {
				item.addClass('has-drop-down');
				if(link.length) link.addClass('arrow');
			}

		});

		generateBreadcrumbs(0, defaultBradcrumbText);
		nodesLoadedHandler(nav.find('[data-toc-url]'));

		function nodesLoadedHandler(link) {
			link.on('nodes-loaded', function() {
				var link = jQuery(this);
				var item = link.closest('li');
				var drop = item.find('> ul');
				var parentList = item.closest('ul');
				var parentItem = parentList.closest('li');

				if(drop.length) {
					item.addClass('has-drop-down');
					if(link.length) link.addClass('arrow');
				}
				// set start level index attr
				// console.log('parentItem', parentItem);
				// console.log('  len', parentItem.length);
				// console.log('  data', parentItem.data('level'));

				// setLevel(parentList, parentItem.length ? parentItem.data('level') : 0);
				setLevel(parentList, parentItem.length && parentItem.data('level') ? parentItem.data('level') : 0);
				arrowClickHandler(parentList);
				showDrop(item, link);

				nodesLoadedHandler(drop.find('[data-toc-url]'));
			});
		}


		// set level index attr
		function setLevel(list, index) {
			// console.warn('set level for', list, index);
			list.children('li:has(ul)').each(function() {
				var item = jQuery(this);
				var drop = item.find('> ul');

				item.attr('data-level', index + 1);
				items = items.add(item);
				// console.log(' * ', index + 1, item);

				setLevel(drop, index + 1);
			});
		}

		// set start level index attr
		setLevel(nav, 0);
		arrowClickHandler(nav);

		// attach bradcrumbs click handler
		bradcrumbs.on('click', 'a', function(e) {
			e.preventDefault();

			var link = jQuery(e.currentTarget);
			var index = link.data('index');
			var item = items.filter('[data-level="' + index + '"]');

			if (bradcrumbsItems.length > 1) {
				hideDrop(item, link);
			}
		});

		function arrowClickHandler(list) {
			list.find('li').each(function() {
				var item = jQuery(this);
				var link = item.find('> .arrow');
				var drop = item.find('> ul');

				drop.prepend('<li class="level-title">' + link.text() + ':</li>');

				// attach link click handler
				link.on('click', function(e) {
					e.preventDefault();

					showDrop(item, link);
				});
			});
		}

		// hide drop
		function hideDrop(item, link) {
			//console.warn('hideDrop');
			item.removeClass(activeItemClass).removeClass(inactiveItemClass);
			item.find('.' + inactiveItemClass).removeClass(inactiveItemClass);
			item.find('.' + activeItemClass).removeClass(activeItemClass);
			item.siblings().removeClass(inactiveItemClass).removeClass(activeItemClass);
			item.siblings().find('.' + inactiveItemClass).removeClass(inactiveItemClass);
			item.siblings().find('.' + activeItemClass).removeClass(inactiveItemClass);

			generateBreadcrumbs(item.data('level'), link.text(), true);
		}

		// show drop
		function showDrop(item, link) {
			item.siblings().removeClass(activeItemClass).addClass(inactiveItemClass);
			item.addClass(activeItemClass).removeClass(inactiveItemClass);

			// console.log('item for bc', item, link);
			generateBreadcrumbs(item.data('level'), link.text());
		}

		// add new breadcrumb
		function addNewBreadcrumb(index, text) {
			bradcrumbsItems[index] = text;
		}

		// generate breadcrumbs
		function generateBreadcrumbs(index, text, bcClick) {
			// console.log('current bc:', bradcrumbsItems);
			bradcrumbsItems.length = index;

			if (!bcClick) {
				addNewBreadcrumb(index, text);
			}
			// console.log('bc after:', bradcrumbsItems);

			bradcrumbs.empty();

			for (var i = 0, length = bradcrumbsItems.length; i < length; i++) {
				bradcrumbs.append('<li><a href="#" data-index="' + (i + 1) + '">' + bradcrumbsItems[i] + '</a></li>');
			}
		}

		// reset active classes
		function resetActive() {
			items.find('.' + activeLinkClass).removeClass(activeLinkClass);

			generateBreadcrumbs(0, defaultBradcrumbText);
		}

		this.tocReset = function() {
			//console.log('in tocReset()');
            nav.find('li.active a').trigger('HideSlide');
		};
		// this.tocReset = resetActive;
	});
}

// init Iframe functions
function initIframeEvents() {
	// detect device type
	var isTouchDevice = /Windows Phone/.test(navigator.userAgent) || ('ontouchstart' in window) || window.DocumentTouch && document instanceof DocumentTouch;
	var scrollHolder = jQuery('#js-viewer-holder');
	var iframe = jQuery('#js-viewer-holder iframe');

	onIframeReady(iframe, false, function($contents) {
		onIframeLoad($contents);

		initIFrameResize(iframe).done(function(iframe){
			// scroll to anchor
			var hash = iframe[0].contentWindow.location.hash;
			var anchorBlock = $contents.find(hash.replace('hit', ''));
			var header = jQuery('#header');
			var extraOffset = (header.length && header.css('position') === 'fixed') ? header.outerHeight() : 0;

			ResponsiveHelper.addRange({
				'768..': {
					on: function() {
						if (hash && hash.length && anchorBlock.length) {
							scrollHolder.scrollTop(anchorBlock.offset().top - extraOffset);
						}
					}
				},
				'..767': {
					on: function() {
						if (hash && hash.length && anchorBlock.length) {
							jQuery('html, body').scrollTop(anchorBlock.offset().top + (scrollHolder.length ? scrollHolder.offset().top : 0) - extraOffset);
						}
					}
				}
			});
		});

	}, function() {
		console.log('Can not access iframe');
	});

	function onIframeLoad($contents) {
		// remove old video popup
		jQuery('#js-sticky-video').remove();

		var videoHolderId = 'js-sticky-video';

		$contents.on('click', 'a[href*="playvideo.asp"]', function(e) {
			e.preventDefault();

			var href = jQuery(this).attr('href');
			// var q = href.
            var sFileName = getUrlParameter(href, 'sFileName');
            var pos = getUrlParameter(href, 'iCurrentPosition');

			console.log('Show video: ', href);


			// video link transformation
			var videoUrl = 'http://vid.opengovideo.com/' +
				'mp4/' + sFileName.replace('http://video.clerkshq.com/', '')  + '.mp4';

			// open player...
			var btn = jQuery(this);
			var videoHolder = jQuery('#' + videoHolderId + '');

			if (!videoHolder.length) {
				videoHolder = jQuery('<div id="' + videoHolderId + '"><button type="button" class="js-video-close"><span></span></button>' +
					'<div style="position: relative; float: right;"><div class="jw-logo jw-logo-top-right jw-reset" tabindex="0" aria-label="Logo" style="background-image: url(&quot;http://www.mytestserver.com/OGVOverlay.png&quot;);width: 96px;height: 22px;z-index: 10000; right: 0;"></div></div>' +
					'<div class="js-video" style="width: ' + (isTouchDevice ? 298 : 400) + 'px; height: ' + (isTouchDevice ? 280 : 225) + 'px; "></div></div>');
				videoHolder.appendTo(jQuery('#js-viewer-holder'));

				videoHolder.on('click', '.js-video-close', function (e) {
					e.preventDefault();
					videoHolder.remove();
				});
			}

            href = href.replace('playvideo', 'playvideoiframe');
			// videoUrl = 'blob:http://vid.opengovideo.com/1d3f0e15-02ba-44a4-96a9-8b420fad4c18';

			// href = "/video.html";

			// var videoFrame = '<iframe src="http://vid.opengovideo.com/playvideoiframe.asp?sFileName=http://video.clerkshq.com/ri_cumberland_towncouncil_20181004&iCurrentPosition=157"></iframe>';
			var videoFrame = '<iframe src="' + href + '" style="width: 100%; height: 100%;" allowfullscreen></iframe>';
			videoHolder.find('.js-video').html(videoFrame);
			// if(true) return;
			//
			// var html5video = jQuery('<video src="blob:' + videoUrl + '" poster="' + (btn.attr('data-poster') || '') + '" controls playsinline XXXautoplay disableremoteplayback></video>');
