// init selection toc
function initSelectionTocCheckboxes() {
	jQuery('.open-fieldset').each(function() {
		var holder = jQuery(this);
		var label = holder.find('.selection-label');
		var tocList = holder.find('.toc-accordion');
		var resetTimer = null;

		function labelRefresh() {
			 var tocCheckboxes = tocList.find('[type="checkbox"]');
			var checkedLength = tocCheckboxes.filter(':checked').length;
			var text = label.data('defaultText');

			if (checkedLength) {
				text = label.data('selectedText');
			}

			if (checkedLength === tocCheckboxes.length) {
				text = label.data('allText');
			}

			label.text(text);
		}

		tocList.on('change', function(e, elem) {
			console.log('change cb');
			var chbox = jQuery(e.target);
			if (jQuery(elem) && jQuery(elem).is('[type="checkbox"]')) {
				chbox = jQuery(elem);
			}
			var item = chbox.closest('li');
			var nodeChboxes = item.find('> ul [type="checkbox"]');

			nodeChboxes.prop('checked', chbox.prop('checked'));

			checkParent(chbox);

			labelRefresh();
		});

		function checkParent(chbox) {
			var item = chbox.closest('li');
			var siblingsChboxes = item.siblings('li').find('> label [type="checkbox"]').add(chbox);
			var parentChbox = item.parents('li').eq(0).find('> label [type="checkbox"]');

			if (parentChbox.length) {
				parentChbox.prop('checked', siblingsChboxes.filter(':checked').length === siblingsChboxes.length);

				checkParent(parentChbox);
			}
		}

		labelRefresh();

		tocList.closest('form').on('reset', function() {
			clearTimeout(resetTimer);
			resetTimer = setTimeout(function() {
				labelRefresh();
			}, 100);
		});
	});
}

